INSERT INTO public.services (slug, icon, title_fa, title_en, description_fa, description_en, detail_fa, detail_en, capabilities_fa, capabilities_en, technologies, sort_order) VALUES ('content', 'content', 'تولید محتوا', 'Content creation', 'تولید محتوای خلاقانه و هدفمند برای افزایش تعامل و فروش', 'Purposeful, original content that inspires engagement and drives growth.', 'از یک ایده‌ی کوچک تا داستانی که در ذهن می‌ماند؛ محتوایی می‌سازیم که درست شبیه برند شما حرف می‌زند.', 'From a small spark to a story worth remembering, we create content that sounds unmistakably like your brand.', ARRAY['استراتژی محتوا','کمپین خلاق','عکاسی و ویدئو','شبکه‌های اجتماعی']::text[], ARRAY['Content strategy','Creative campaigns','Photography & film','Social media']::text[], ARRAY['Art Direction','Storytelling','Motion']::text[], 0) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.services (slug, icon, title_fa, title_en, description_fa, description_en, detail_fa, detail_en, capabilities_fa, capabilities_en, technologies, sort_order) VALUES ('mobile', 'mobile', 'اپلیکیشن موبایل', 'Mobile applications', 'طراحی و توسعه اپلیکیشن‌های کاربرپسند برای iOS و Android', 'Thoughtful, intuitive mobile experiences for iOS and Android.', 'تجربه‌هایی روان و دوست‌داشتنی طراحی می‌کنیم که زندگی روزمره‌ی کاربران را ساده‌تر می‌کنند.', 'We design fluid, useful digital products that make everyday life feel a little simpler.', ARRAY['تحقیق کاربر','طراحی محصول','نمونه‌سازی','توسعه اپلیکیشن']::text[], ARRAY['User research','Product design','Prototyping','App development']::text[], ARRAY['iOS','Android','Figma']::text[], 1) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.services (slug, icon, title_fa, title_en, description_fa, description_en, detail_fa, detail_en, capabilities_fa, capabilities_en, technologies, sort_order) VALUES ('web', 'web', 'طراحی و توسعه وب', 'Web design & development', 'طراحی سایت‌های مدرن و توسعه با جدیدترین تکنولوژی‌ها', 'Distinctive websites built with modern technology and human intuition.', 'وب‌سایت‌هایی سریع، دسترس‌پذیر و متمایز که از اولین نگاه تا آخرین تعامل، برند شما را زنده می‌کنند.', 'Fast, accessible and distinctive websites that bring your brand to life from the first impression to the final interaction.', ARRAY['تجربه کاربری','طراحی رابط','توسعه فرانت‌اند','وب‌سایت تعاملی']::text[], ARRAY['User experience','Interface design','Front-end development','Interactive websites']::text[], ARRAY['HTML / CSS','JavaScript','WebGL']::text[], 2) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.services (slug, icon, title_fa, title_en, description_fa, description_en, detail_fa, detail_en, capabilities_fa, capabilities_en, technologies, sort_order) VALUES ('branding', 'branding', 'برندینگ', 'Branding', 'خلق هویت بصری متمایز و ساخت برندهای ماندگار', 'Building memorable brands with distinctive visual identities.', 'هویتی می‌سازیم که فقط زیبا نیست؛ معنایی روشن دارد، در هر نقطه‌ی تماس منسجم است و در ذهن می‌ماند.', 'We create identities that are more than beautiful: meaningful, consistent and impossible to forget.', ARRAY['استراتژی برند','هویت بصری','لحن برند','راهنمای برند']::text[], ARRAY['Brand strategy','Visual identity','Tone of voice','Brand guidelines']::text[], ARRAY['Brand Strategy','Identity','Art Direction']::text[], 3) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.projects (slug, title_fa, title_en, category, client_fa, client_en, year, summary_fa, summary_en, description_fa, description_en, cover, images, technologies, featured, sort_order) VALUES ('nova-architecture', 'نووا؛ معماریِ فردا', 'NOVA Architecture', 'branding', 'استودیو نووا', 'NOVA Studio', 2025, 'هویت بصری برای فضایی فراتر از معماری', 'An identity for a space beyond architecture', 'نووا مرز میان فضا و احساس را بازتعریف می‌کند. ما با الهام از فرم‌های معماری، هویتی ساختیم که سکوت، جسارت و نگاه رو به آینده‌ی این استودیو را به تصویر می‌کشد.', 'NOVA reimagines the space between architecture and emotion. Inspired by elemental forms, we created an identity that captures the studio’s quiet confidence and forward-looking spirit.', 'assets/work-nova.webp', '["assets/work-nova.webp", "assets/detail-nova.webp"]'::jsonb, ARRAY['Brand Strategy','Visual Identity','Web Design']::text[], true, 0) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.projects (slug, title_fa, title_en, category, client_fa, client_en, year, summary_fa, summary_en, description_fa, description_en, cover, images, technologies, featured, sort_order) VALUES ('seda-sound', 'صدا؛ تجربه‌ای شنیدنی', 'SEDA Sound', 'web', 'صدا', 'SEDA', 2025, 'تجربه دیجیتال برای دنیای صدا', 'A digital experience for the world of sound', 'برای صدا، یک تجربه‌ی دیجیتال خلق کردیم که انرژی و عمق موسیقی را به زبان تصویر ترجمه می‌کند؛ جایی که هر تعامل، آهنگ خودش را دارد.', 'For SEDA we created a digital experience that translates the energy and depth of sound into a visual language, where every interaction has its own rhythm.', 'assets/work-seda.webp', '["assets/work-seda.webp", "assets/detail-seda.webp"]'::jsonb, ARRAY['Digital Strategy','UX / UI','WebGL']::text[], true, 1) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.projects (slug, title_fa, title_en, category, client_fa, client_en, year, summary_fa, summary_en, description_fa, description_en, cover, images, technologies, featured, sort_order) VALUES ('kaan-beauty', 'کان؛ زیباییِ بی‌واسطه', 'KAAN Beauty', 'branding', 'کان', 'KAAN', 2024, 'برندی آرام، صادق و به‌یادماندنی', 'A quiet, honest and memorable beauty brand', 'کان داستان مراقبت با نگاهی تازه است. از استراتژی تا هویت بصری و حضور دیجیتال، دنیایی ساختیم که سادگی را با جزئیات معنادار همراه می‌کند.', 'KAAN is a fresh story of care. From strategy and visual identity to digital presence, we created a world where simplicity and meaningful detail meet.', 'assets/work-kaan.webp', '["assets/work-kaan.webp", "assets/detail-kaan.webp"]'::jsonb, ARRAY['Brand Identity','Art Direction','Packaging']::text[], true, 2) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.projects (slug, title_fa, title_en, category, client_fa, client_en, year, summary_fa, summary_en, description_fa, description_en, cover, images, technologies, featured, sort_order) VALUES ('rah-travel', 'راه؛ کشفِ مسیر تازه', 'RAH Travel', 'mobile', 'راه', 'RAH', 2024, 'سفری ساده‌تر، تجربه‌ای عمیق‌تر', 'Simpler journeys, richer experiences', 'راه پلتفرمی برای کشف تجربه‌های تازه است. ما سفری دیجیتال طراحی کردیم که برنامه‌ریزی را ساده و لحظه‌ی کشف را هیجان‌انگیز می‌کند.', 'RAH is a platform for discovering new experiences. We designed a digital journey that makes planning simple and discovery exciting.', 'assets/work-rah.webp', '["assets/work-rah.webp", "assets/detail-rah.webp"]'::jsonb, ARRAY['Product Design','iOS','Android']::text[], true, 3) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.projects (slug, title_fa, title_en, category, client_fa, client_en, year, summary_fa, summary_en, description_fa, description_en, cover, images, technologies, featured, sort_order) VALUES ('veera-finance', 'ویرا؛ آینده مالی روشن', 'VEERA Finance', 'mobile', 'ویرا', 'VEERA', 2024, 'طراحی محصول برای یک زندگی مالی بهتر', 'A product for a better financial life', 'ویرا به آدم‌ها کمک می‌کند تصمیم‌های مالی را با اطمینان بیشتری بگیرند. تجربه‌ای روشن، انسانی و قابل اعتماد برای همراهی در هر قدم.', 'VEERA helps people make financial decisions with confidence. A clear, human and trustworthy experience at every step.', 'assets/work-veera.webp', '["assets/work-veera.webp", "assets/detail-veera.webp"]'::jsonb, ARRAY['Research','Product Design','Mobile']::text[], false, 4) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.projects (slug, title_fa, title_en, category, client_fa, client_en, year, summary_fa, summary_en, description_fa, description_en, cover, images, technologies, featured, sort_order) VALUES ('roshd-platform', 'رشد؛ یادگیری بی‌مرز', 'ROSHD Learning', 'web', 'رشد', 'ROSHD', 2023, 'یک تجربه یادگیری برای نسل آینده', 'A learning experience for the next generation', 'با رشد، بستری ساختیم که یادگیری را از یک وظیفه به یک تجربه‌ی الهام‌بخش تبدیل می‌کند.', 'With ROSHD, we built a platform that turns learning from a task into an inspiring experience.', 'assets/work-roshd.webp', '["assets/work-roshd.webp", "assets/detail-roshd.webp"]'::jsonb, ARRAY['UX Strategy','Web Design','Development']::text[], false, 5) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.projects (slug, title_fa, title_en, category, client_fa, client_en, year, summary_fa, summary_en, description_fa, description_en, cover, images, technologies, featured, sort_order) VALUES ('noon-campaign', 'نون؛ داستان هر روز', 'NOON Campaign', 'content', 'نون', 'NOON', 2023, 'محتوایی برای لحظه‌های واقعی زندگی', 'Stories for the real moments of everyday life', 'برای نون، کمپینی ساختیم که از لحظه‌های ساده‌ی زندگی شروع می‌شود و به داستانی مشترک می‌رسد.', 'For NOON we created a campaign rooted in the simple moments of life and the stories we share.', 'assets/work-noon.webp', '["assets/work-noon.webp", "assets/detail-noon.webp"]'::jsonb, ARRAY['Campaign','Content','Art Direction']::text[], false, 6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.projects (slug, title_fa, title_en, category, client_fa, client_en, year, summary_fa, summary_en, description_fa, description_en, cover, images, technologies, featured, sort_order) VALUES ('avar-living', 'آوار؛ زندگی در جزئیات', 'AVAR Living', 'branding', 'آوار', 'AVAR', 2023, 'هویت تازه برای شیوه‌ای تازه از زیستن', 'A new identity for a new way of living', 'آوار از جزئیات روزمره الهام می‌گیرد. هویت آن را با ترکیبی از جسارت، گرما و نگاه انسانی شکل دادیم.', 'AVAR finds inspiration in everyday details. We shaped its identity around boldness, warmth and a human perspective.', 'assets/work-avar.webp', '["assets/work-avar.webp", "assets/detail-avar.webp"]'::jsonb, ARRAY['Brand Strategy','Identity','Digital']::text[], false, 7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.blog_posts (slug, title_fa, title_en, category_fa, category_en, excerpt_fa, excerpt_en, body_fa, body_en, published_at, read_minutes, cover, sort_order) VALUES ('brand-story', 'چرا هر برند به یک داستان خوب نیاز دارد؟', 'Why every brand needs a good story', 'برندینگ', 'Branding', 'یک داستان خوب، فاصله‌ی میان یک کسب‌وکار و مخاطبانش را کم می‌کند.', 'A good story closes the distance between a business and its audience.', 'برندها فقط با محصولاتشان شناخته نمی‌شوند؛ آنچه در ذهن می‌ماند احساسی است که می‌سازند. یک داستان روشن به مخاطب کمک می‌کند بفهمد شما به چه چیزی باور دارید و چرا حضورتان مهم است.
INSERT INTO public.blog_posts (slug, title_fa, title_en, category_fa, category_en, excerpt_fa, excerpt_en, body_fa, body_en, published_at, read_minutes, cover, sort_order) VALUES ('design-for-humans', 'طراحی برای آدم‌ها، نه فقط صفحه‌ها', 'Design for people, not just screens', 'طراحی', 'Design', 'چطور با همدلی، تجربه‌های دیجیتال بهتری بسازیم؟', 'How empathy helps us build better digital experiences.', 'طراحی خوب از درک آدم‌ها آغاز می‌شود. پیش از انتخاب رنگ و ساختن صفحه، باید بفهمیم کاربر چه می‌خواهد و چه چیزی راهش را سخت می‌کند.
INSERT INTO public.blog_posts (slug, title_fa, title_en, category_fa, category_en, excerpt_fa, excerpt_en, body_fa, body_en, published_at, read_minutes, cover, sort_order) VALUES ('motion-with-purpose', 'حرکت هدفمند در تجربه دیجیتال', 'Motion with meaning in digital experiences', 'موشن', 'Motion', 'انیمیشن زمانی ارزشمند است که به معنا و مسیر کاربر کمک کند.', 'Animation matters when it supports meaning and the user journey.', 'حرکت می‌تواند توجه را هدایت کند، رابطه‌ی میان عناصر را نشان دهد و به تجربه شخصیت بدهد. اما هر حرکتی باید دلیلی داشته باشد.
INSERT INTO public.blog_posts (slug, title_fa, title_en, category_fa, category_en, excerpt_fa, excerpt_en, body_fa, body_en, published_at, read_minutes, cover, sort_order) VALUES ('building-digital-trust', 'اعتماد در دنیای دیجیتال چگونه ساخته می‌شود؟', 'How to build trust in a digital world', 'استراتژی', 'Strategy', 'جزئیات کوچک و تجربه‌های منسجم، اعتمادهای بزرگ می‌سازند.', 'Small details and consistent experiences create lasting trust.', 'اعتماد یک ویژگی تزئینی نیست؛ نتیجه‌ی وعده‌های روشن و تجربه‌های قابل پیش‌بینی است.
INSERT INTO public.blog_posts (slug, title_fa, title_en, category_fa, category_en, excerpt_fa, excerpt_en, body_fa, body_en, published_at, read_minutes, cover, sort_order) VALUES ('creative-process', 'از ایده تا اجرا: پشت صحنه‌ی یک فرایند خلاق', 'From idea to execution: the creative process', 'ایده‌پردازی', 'Ideas', 'ایده‌های بزرگ از پرسش‌های دقیق و همکاری خوب شکل می‌گیرند.', 'Big ideas begin with thoughtful questions and good collaboration.', 'هیچ ایده‌ای در خلأ شکل نمی‌گیرد. ما با گوش دادن، تحقیق و ساختن تصویری مشترک از مسئله شروع می‌کنیم.
INSERT INTO public.blog_posts (slug, title_fa, title_en, category_fa, category_en, excerpt_fa, excerpt_en, body_fa, body_en, published_at, read_minutes, cover, sort_order) VALUES ('future-of-brands', 'آینده‌ی برندها انسانی‌تر است', 'The future of brands is more human', 'نگاه تازه', 'Perspective', 'در جهانی پر از فناوری، ارتباط انسانی مهم‌تر از همیشه است.', 'In a technology-filled world, human connection matters more than ever.', 'فناوری ابزارهای تازه‌ای در اختیار ما گذاشته، اما نیاز انسان به ارتباط، معنا و اعتماد تغییر نکرده است.
