INSERT INTO public.team_members (name_fa, name_en, role_fa, role_en, color, sort_order) VALUES ('یاسمن راد', 'Yasaman Rad', 'استراتژیست برند', 'Brand Strategist', '#83627d', 2);
INSERT INTO public.team_members (name_fa, name_en, role_fa, role_en, color, sort_order) VALUES ('مانی رستگار', 'Mani Rastegar', 'توسعه‌دهنده خلاق', 'Creative Developer', '#4a5c7f', 3);
INSERT INTO public.testimonials (quote_fa, quote_en, name_fa, name_en, role_fa, role_en, initials, sort_order) VALUES ('ایده‌پردازان فقط یک هویت بصری برای ما نساختند؛ آن‌ها واقعاً داستان برند ما را فهمیدند و به آن جان تازه‌ای بخشیدند.', 'Idehpardazan did more than create a visual identity. They truly understood our story and brought it to life in a completely new way.', 'سارا نیک‌فر', 'Sara Nikfar', 'مدیر برند، نووا', 'Brand Director, NOVA', 'SN', 0);
INSERT INTO public.testimonials (quote_fa, quote_en, name_fa, name_en, role_fa, role_en, initials, sort_order) VALUES ('همکاری با این تیم ترکیبی از تفکر عمیق، خلاقیت و توجه وسواس‌گونه به جزئیات بود. نتیجه فراتر از انتظار ما شد.', 'Working with the team was a combination of deep thinking, creativity and meticulous attention to detail. The result exceeded our expectations.', 'آرش زمانی', 'Arash Zamani', 'بنیان‌گذار، صدا', 'Founder, SEDA', 'AZ', 1);
INSERT INTO public.testimonials (quote_fa, quote_en, name_fa, name_en, role_fa, role_en, initials, sort_order) VALUES ('آن‌ها به‌خوبی توانستند پیچیدگی محصول ما را به تجربه‌ای ساده و دوست‌داشتنی تبدیل کنند.', 'They translated the complexity of our product into an experience that feels simple and genuinely enjoyable.', 'نگین کاویانی', 'Negin Kaviani', 'مدیر محصول، ویرا', 'Product Lead, VEERA', 'NK', 2);
INSERT INTO public.testimonials (quote_fa, quote_en, name_fa, name_en, role_fa, role_en, initials, sort_order) VALUES ('از اولین گفتگو تا آخرین جزئیات، حس می‌کردیم با تیمی هم‌فکر و متعهد در کنار هم کار می‌کنیم.', 'From the first conversation to the final detail, it felt like working with a thoughtful and committed partner.', 'پرهام راد', 'Parham Rad', 'مدیر بازاریابی، کان', 'Marketing Director, KAAN', 'PR', 3);
INSERT INTO public.testimonials (quote_fa, quote_en, name_fa, name_en, role_fa, role_en, initials, sort_order) VALUES ('نتیجه فقط زیبا نبود؛ روشن، کاربردی و کاملاً هماهنگ با چشم‌انداز ما بود.', 'The result was not only beautiful; it was clear, useful and completely aligned with our vision.', 'مریم نادری', 'Maryam Naderi', 'مدیر اجرایی، رشد', 'CEO, ROSHD', 'MN', 4);
